<code>
#!/usr/bin/env perl -w
use File::Find;
use File::Copy;
use File::Basename;
use File::Basename;
use File::Slurp;

use POSIX qw(strftime);

my $date = strftime("%m-%d-%y",localtime);
my $time = strftime("%I:%M:%S",localtime);


my $findme = "/Volumes/photorepos/Perl/SLAperlDropback/";
my $file_loc = $findme. '2SLAday';
my $filenames_to_putback = '/Volumes/photorepos/Perl/SLAperlDropback/dropback.txt';


chdir($file_loc) or warn  "$!";
@filesforeach = glob "*.*";
my $filecount = @filesforeach;
print "$filecount\n";
chomp @filesforeach;
foreach $file (@filesforeach){
print "$file\n";



open(my $fh, "<", "$filenames_to_putback") or warn "$!\n";
while (my $row = <$fh>) {
  chomp $row;
  print "$row\n";

my @line = $file;
  for (@line) {
    if ($_ =~ /$row/) {
    chomp $_;
#   push @output, "found $_ that matched redo $file $row <br>";
  move($_,$row) or warn "shit went wrong yo! $!\n";
}
}
}
}
